import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC02%E7%AB%A0%20%E4%BF%A1%E6%81%AF%E6%8A%80%E6%9C%AF%E5%8F%91%E5%B1%95/2.2%20%E6%96%B0%E6%8A%80%E6%9C%AF%E5%8F%91%E5%B1%95.html","title":"2.2 新技术发展","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第02章 信息技术发展/2.2 新技术发展.md"}`),a={name:`2.2 新技术发展.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_2-2-新技术发展" tabindex="-1"><a class="header-anchor" href="#_2-2-新技术发展"><span>2.2 新技术发展</span></a></h1><h2 id="云计算" tabindex="-1"><a class="header-anchor" href="#云计算"><span>云计算</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>云计算是一种基于互联网的计算方式，通过网络提供动态、可扩展的虚拟化资源。</p><h3 id="服务模式" tabindex="-1"><a class="header-anchor" href="#服务模式"><span>服务模式</span></a></h3><table><thead><tr><th>模式</th><th>全称</th><th>描述</th></tr></thead><tbody><tr><td><strong>IaaS</strong></td><td>Infrastructure as a Service</td><td>基础设施即服务，提供虚拟机、存储等</td></tr><tr><td><strong>PaaS</strong></td><td>Platform as a Service</td><td>平台即服务，提供开发平台和工具</td></tr><tr><td><strong>SaaS</strong></td><td>Software as a Service</td><td>软件即服务，提供完整的应用程序</td></tr></tbody></table><h3 id="特点" tabindex="-1"><a class="header-anchor" href="#特点"><span>特点</span></a></h3><ul><li><strong>按需服务</strong>：根据需求动态分配资源</li><li><strong>弹性扩展</strong>：可快速扩展或收缩资源</li><li><strong>付费模式</strong>：按使用量付费</li><li><strong>高可靠性</strong>：多副本冗余</li></ul><h2 id="大数据" tabindex="-1"><a class="header-anchor" href="#大数据"><span>大数据</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>大数据是指无法在一定时间内用常规软件工具对其内容进行抓取、管理和处理的数据集合。</p><h3 id="特征-5v" tabindex="-1"><a class="header-anchor" href="#特征-5v"><span>特征（5V）</span></a></h3><table><thead><tr><th>特征</th><th>含义</th></tr></thead><tbody><tr><td><strong>Volume</strong></td><td>数据量大</td></tr><tr><td><strong>Velocity</strong></td><td>处理速度快</td></tr><tr><td><strong>Variety</strong></td><td>数据类型多样</td></tr><tr><td><strong>Value</strong></td><td>价值密度低</td></tr><tr><td><strong>Veracity</strong></td><td>数据真实性</td></tr></tbody></table><h3 id="技术体系" tabindex="-1"><a class="header-anchor" href="#技术体系"><span>技术体系</span></a></h3><ul><li>数据采集：传感器、日志、社交媒体</li><li>数据存储：分布式存储（HDFS）</li><li>数据处理：MapReduce、Spark</li><li>数据分析：数据挖掘、机器学习</li></ul><h2 id="人工智能" tabindex="-1"><a class="header-anchor" href="#人工智能"><span>人工智能</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><p>人工智能是使计算机系统能够模拟、延伸和扩展人类智能的技术。</p><h3 id="核心技术" tabindex="-1"><a class="header-anchor" href="#核心技术"><span>核心技术</span></a></h3><ul><li><strong>机器学习</strong>：让计算机从数据中学习</li><li><strong>深度学习</strong>：基于神经网络的学习方法</li><li><strong>自然语言处理</strong>：理解和生成人类语言</li><li><strong>计算机视觉</strong>：识别和理解图像、视频</li></ul><h3 id="应用领域" tabindex="-1"><a class="header-anchor" href="#应用领域"><span>应用领域</span></a></h3><ul><li>智能语音助手</li><li>自动驾驶</li><li>医疗诊断</li><li>金融风控</li></ul><h2 id="物联网" tabindex="-1"><a class="header-anchor" href="#物联网"><span>物联网</span></a></h2><h3 id="定义-3" tabindex="-1"><a class="header-anchor" href="#定义-3"><span>定义</span></a></h3><p>物联网是通过信息传感设备，按约定协议，将物品与互联网相连接，进行信息交换和通信。</p><h3 id="架构" tabindex="-1"><a class="header-anchor" href="#架构"><span>架构</span></a></h3><ul><li><strong>感知层</strong>：传感器、RFID、摄像头</li><li><strong>网络层</strong>：互联网、通信网络</li><li><strong>应用层</strong>：智能城市、智慧家居、工业物联网</li></ul><h2 id="区块链" tabindex="-1"><a class="header-anchor" href="#区块链"><span>区块链</span></a></h2><h3 id="定义-4" tabindex="-1"><a class="header-anchor" href="#定义-4"><span>定义</span></a></h3><p>区块链是一种分布式账本技术，通过去中心化和加密技术保证数据的安全性和不可篡改性。</p><h3 id="特点-1" tabindex="-1"><a class="header-anchor" href="#特点-1"><span>特点</span></a></h3><ul><li>去中心化</li><li>不可篡改</li><li>透明可追溯</li><li>智能合约</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>云计算三种服务模式的区别</strong></li><li><strong>大数据的5V特征</strong></li><li><strong>人工智能的核心技术</strong></li><li><strong>物联网的三层架构</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>云大物移智区块，新技引领数字化</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪种云计算服务模式提供虚拟机和存储资源？ A. IaaS B. PaaS C. SaaS D. DaaS</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>：IaaS（基础设施即服务）提供虚拟机、存储等基础设施资源。PaaS提供开发平台，SaaS提供完整应用。</p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};